const adapter = registry.find(x => x.matches(validatedURL));
const session = await adapter.mount(container);
inspector.record({provider: adapter.id, evidence: await session.probe()});

const feed = await adapter.readChannel(channelId); // una solicitud
const videos = feed.items.map(normalize).filter(valid).sort(byNewest).slice(0,3);
mountVideo(videos[0].id); // reproductor activo

async function openTool(id) {
  const {createAdapter} = await import(`./adapters/${allowlistedId(id)}.mjs`);
  return createAdapter().mount(windowNode);
}

const match = resolveOfficialPost(new URL(userUrl));
if (!match) return renderExternal(validExternalUrl);
const adapter = await import(match.adapter);
return adapter.mount(match.canonicalUrl);
